namespace sv_6e89210bbe024f549345a964d003f3cb.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@using sv_6e89210bbe024f549345a964d003f3cb.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(toastMessage))
        {
            <div class="toast @toastType">
                @toastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }

        @if (activeSection == "Profile")
        {
            <section class="settings-section">
                <h2>Profile Settings</h2>
                @if (profile is not null)
                {
                    <div class="form-group avatar-group">
                        <label>Avatar</label>
                        <div class="avatar-preview">
                            @if (!string.IsNullOrEmpty(editDisplayName))
                            {
                                <img src="@editAvatarUrl" alt="Avatar" class="avatar-img" />
                            }
                        </div>
                        <span class="avatar-url">@editAvatarUrl</span>
                    </div>
                    <div class="form-group">
                        <label for="displayName">Display Name</label>
                        <input id="displayName" type="text" @bind="editDisplayName" />
                    </div>
                    <div class="form-group">
                        <label for="email">Email</label>
                        <input id="email" type="email" @bind="editEmail" />
                    </div>
                    <div class="form-group">
                        <label for="bio">Bio</label>
                        <textarea id="bio" @bind="editBio" rows="4"></textarea>
                    </div>
                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                        <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                    </div>
                }
                else
                {
                    <p>Loading profile...</p>
                }
            </section>
        }
        else if (activeSection == "Notifications")
        {
            <section class="settings-section">
                <h2>Notification Preferences</h2>
                @if (notificationPrefs is not null)
                {
                    <div class="form-group toggle-group">
                        <label class="toggle-label">
                            <span>Email Notifications</span>
                            <label class="switch">
                                <input type="checkbox" @bind="editEmailNotifications" />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>
                    <div class="form-group toggle-group">
                        <label class="toggle-label">
                            <span>Push Notifications</span>
                            <label class="switch">
                                <input type="checkbox" @bind="editPushNotifications" />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>
                    <div class="form-group toggle-group">
                        <label class="toggle-label">
                            <span>Weekly Digest</span>
                            <label class="switch">
                                <input type="checkbox" @bind="editWeeklyDigest" />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>

                    <h3>Muted Channels</h3>
                    <div class="channel-list">
                        @foreach (var channel in availableChannels)
                        {
                            <label class="channel-item">
                                <input type="checkbox"
                                       checked="@editMutedChannels.Contains(channel)"
                                       @onchange="e => ToggleMutedChannel(channel, (bool)(e.Value ?? false))" />
                                <span>@channel</span>
                            </label>
                        }
                    </div>
                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                    </div>
                }
                else
                {
                    <p>Loading notification preferences...</p>
                }
            </section>
        }
        else if (activeSection == "Security")
        {
            <section class="settings-section">
                <h2>Security Settings</h2>
                @if (securitySettings is not null)
                {
                    <div class="expandable-panel">
                        <button class="panel-header" @onclick="TogglePasswordPanel">
                            <span>Change Password</span>
                            <span class="expand-icon">@(showPasswordPanel ? "▼" : "▶")</span>
                        </button>
                        @if (showPasswordPanel)
                        {
                            <div class="panel-body">
                                <div class="form-group">
                                    <label for="currentPassword">Current Password</label>
                                    <input id="currentPassword" type="password" @bind="currentPassword" />
                                </div>
                                <div class="form-group">
                                    <label for="newPassword">New Password</label>
                                    <input id="newPassword" type="password" @bind="newPassword" />
                                </div>
                                <div class="form-group">
                                    <label for="confirmPassword">Confirm Password</label>
                                    <input id="confirmPassword" type="password" @bind="confirmPassword" />
                                </div>
                                <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                            </div>
                        }
                    </div>

                    <div class="form-group toggle-group">
                        <label class="toggle-label">
                            <span>Two-Factor Authentication</span>
                            <span class="status-indicator @(securitySettings.TwoFactorEnabled ? "status-enabled" : "status-disabled")">
                                @(securitySettings.TwoFactorEnabled ? "Enabled" : "Disabled")
                            </span>
                            <label class="switch">
                                <input type="checkbox" checked="@securitySettings.TwoFactorEnabled" disabled />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>

                    @if (securitySettings.LastPasswordChange.HasValue)
                    {
                        <p class="info-text">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                    }

                    <h3>Active Sessions</h3>
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th>Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in securitySettings.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td>
                                        @if (session != securitySettings.Sessions.First())
                                        {
                                            <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>

                    @if (showRevokeConfirmation)
                    {
                        <div class="modal-overlay">
                            <div class="modal-dialog">
                                <h3>Revoke Session</h3>
                                <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke?.Device</strong> from <strong>@sessionToRevoke?.Location</strong>?</p>
                                <div class="button-group">
                                    <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
                                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                </div>
                            </div>
                        </div>
                    }
                }
                else
                {
                    <p>Loading security settings...</p>
                }
            </section>
        }
        else if (activeSection == "Appearance")
        {
            <section class="settings-section">
                <h2>Appearance Settings</h2>
                @if (appearanceSettings is not null)
                {
                    <div class="form-group">
                        <label>Theme</label>
                        <div class="radio-group">
                            <label class="radio-item">
                                <input type="radio" name="theme" value="Light" checked="@(editTheme == "Light")" @onchange='() => editTheme = "Light"' />
                                <span>Light</span>
                            </label>
                            <label class="radio-item">
                                <input type="radio" name="theme" value="Dark" checked="@(editTheme == "Dark")" @onchange='() => editTheme = "Dark"' />
                                <span>Dark</span>
                            </label>
                            <label class="radio-item">
                                <input type="radio" name="theme" value="System" checked="@(editTheme == "System")" @onchange='() => editTheme = "System"' />
                                <span>System</span>
                            </label>
                        </div>
                    </div>

                    <div class="form-group">
                        <label>Font Size</label>
                        <div class="radio-group">
                            <label class="radio-item">
                                <input type="radio" name="fontSize" value="Small" checked="@(editFontSize == "Small")" @onchange='() => editFontSize = "Small"' />
                                <span>Small</span>
                            </label>
                            <label class="radio-item">
                                <input type="radio" name="fontSize" value="Medium" checked="@(editFontSize == "Medium")" @onchange='() => editFontSize = "Medium"' />
                                <span>Medium</span>
                            </label>
                            <label class="radio-item">
                                <input type="radio" name="fontSize" value="Large" checked="@(editFontSize == "Large")" @onchange='() => editFontSize = "Large"' />
                                <span>Large</span>
                            </label>
                        </div>
                    </div>

                    <div class="form-group">
                        <label for="language">Language</label>
                        <select id="language" @bind="editLanguage">
                            <option value="en">English</option>
                            <option value="es">Spanish</option>
                            <option value="fr">French</option>
                            <option value="de">German</option>
                            <option value="ja">Japanese</option>
                            <option value="zh">Chinese</option>
                        </select>
                    </div>

                    <div class="form-group toggle-group">
                        <label class="toggle-label">
                            <span>Compact Mode</span>
                            <label class="switch">
                                <input type="checkbox" @bind="editCompactMode" />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>

                    <div class="live-preview" style="@GetPreviewStyle()">
                        <h4>Live Preview</h4>
                        <p>This is how your content will look with the selected settings.</p>
                        <p>The quick brown fox jumps over the lazy dog.</p>
                    </div>

                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                    </div>
                }
                else
                {
                    <p>Loading appearance settings...</p>
                }
            </section>
        }
    </main>
</div>

@code {
    private string activeSection = "Profile";

    // Toast
    private string? toastMessage;
    private string toastType = "success";

    // Profile
    private UserProfile? profile;
    private string editDisplayName = "";
    private string editEmail = "";
    private string editAvatarUrl = "";
    private string editBio = "";

    // Notifications
    private NotificationPrefs? notificationPrefs;
    private bool editEmailNotifications;
    private bool editPushNotifications;
    private bool editWeeklyDigest;
    private List<string> editMutedChannels = new();
    private List<string> availableChannels = new() { "general", "announcements", "random", "engineering", "design", "marketing" };

    // Security
    private SecuritySettings? securitySettings;
    private bool showPasswordPanel;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool showRevokeConfirmation;
    private ActiveSession? sessionToRevoke;

    // Appearance
    private AppearanceSettings? appearanceSettings;
    private string editTheme = "Light";
    private string editFontSize = "Medium";
    private string editLanguage = "en";
    private bool editCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
    }

    private void SetSection(string section)
    {
        activeSection = section;
        _ = LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        switch (activeSection)
        {
            case "Profile":
                await LoadProfile();
                break;
            case "Notifications":
                await LoadNotifications();
                break;
            case "Security":
                await LoadSecurity();
                break;
            case "Appearance":
                await LoadAppearance();
                break;
        }
        StateHasChanged();
    }

    // Profile methods
    private async Task LoadProfile()
    {
        profile = await SettingsService.GetProfileAsync();
        ResetProfileFields();
    }

    private void ResetProfileFields()
    {
        if (profile is null) return;
        editDisplayName = profile.DisplayName;
        editEmail = profile.Email;
        editAvatarUrl = profile.AvatarUrl;
        editBio = profile.Bio;
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(editDisplayName, editEmail, editAvatarUrl, editBio);
        await SettingsService.SaveProfileAsync(updated);
        profile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        ResetProfileFields();
        ShowToast("Changes discarded.", "info");
    }

    // Notifications methods
    private async Task LoadNotifications()
    {
        notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
        editEmailNotifications = notificationPrefs.EmailNotifications;
        editPushNotifications = notificationPrefs.PushNotifications;
        editWeeklyDigest = notificationPrefs.WeeklyDigest;
        editMutedChannels = new List<string>(notificationPrefs.MutedChannels);
    }

    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted && !editMutedChannels.Contains(channel))
            editMutedChannels.Add(channel);
        else if (!isMuted)
            editMutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var updated = new NotificationPrefs(editEmailNotifications, editPushNotifications, editWeeklyDigest, editMutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(updated);
        notificationPrefs = updated;
        ShowToast("Notification preferences saved!", "success");
    }

    // Security methods
    private async Task LoadSecurity()
    {
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private void TogglePasswordPanel() => showPasswordPanel = !showPasswordPanel;

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(newPassword) || newPassword != confirmPassword)
        {
            ShowToast("Passwords do not match.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        showPasswordPanel = false;
        ShowToast("Password updated successfully!", "success");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeConfirmation = true;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            showRevokeConfirmation = false;
            sessionToRevoke = null;
            await LoadSecurity();
            ShowToast("Session revoked.", "success");
        }
    }

    private void CancelRevoke()
    {
        showRevokeConfirmation = false;
        sessionToRevoke = null;
    }

    // Appearance methods
    private async Task LoadAppearance()
    {
        appearanceSettings = await SettingsService.GetAppearanceAsync();
        editTheme = appearanceSettings.Theme;
        editFontSize = appearanceSettings.FontSize;
        editLanguage = appearanceSettings.Language;
        editCompactMode = appearanceSettings.CompactMode;
    }

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(editTheme, editFontSize, editLanguage, editCompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        appearanceSettings = updated;
        ShowToast("Appearance settings saved!", "success");
    }

    private string GetPreviewStyle()
    {
        var bg = editTheme == "Dark" ? "#1e1e1e" : "#ffffff";
        var color = editTheme == "Dark" ? "#e0e0e0" : "#333333";
        var fontSize = editFontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.25rem",
            _ => "1rem"
        };
        var padding = editCompactMode ? "0.5rem" : "1.5rem";
        return $"background-color:{bg};color:{color};font-size:{fontSize};padding:{padding};border-radius:8px;border:1px solid #ccc;margin-top:1rem;";
    }

    // Toast
    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
    }

    private void DismissToast() => toastMessage = null;
}

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

.settings-sidebar {
    width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-size: 0.95rem;
    color: #555;
    transition: all 0.2s;
    border-left: 3px solid transparent;
}

.settings-sidebar li:hover {
    background: #e9ecef;
    color: #333;
}

.settings-sidebar li.active {
    background: #e3f2fd;
    color: #1976d2;
    border-left-color: #1976d2;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.1rem;
}

.settings-content {
    flex: 1;
    padding: 2rem 3rem;
    max-width: 800px;
    position: relative;
}

.settings-section h2 {
    margin-bottom: 1.5rem;
    color: #333;
    font-size: 1.5rem;
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
    color: #555;
    font-size: 1.1rem;
}

/* Toast */
.toast {
    position: fixed;
    top: 1rem;
    right: 1rem;
    padding: 0.75rem 1.25rem;
    border-radius: 6px;
    color: #fff;
    font-weight: 500;
    display: flex;
    align-items: center;
    gap: 1rem;
    z-index: 1000;
    animation: slideIn 0.3s ease;
}

.toast.success { background: #43a047; }
.toast.error { background: #e53935; }
.toast.info { background: #1e88e5; }

.toast-close {
    background: none;
    border: none;
    color: #fff;
    cursor: pointer;
    font-size: 1rem;
}

@keyframes slideIn {
    from { transform: translateX(100%); opacity: 0; }
    to { transform: translateX(0); opacity: 1; }
}

/* Form */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #444;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.6rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #1976d2;
    box-shadow: 0 0 0 2px rgba(25, 118, 210, 0.15);
}

/* Avatar */
.avatar-group {
    display: flex;
    align-items: center;
    gap: 1rem;
    flex-wrap: wrap;
}

.avatar-preview {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: #e0e0e0;
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
}

.avatar-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-url {
    font-size: 0.8rem;
    color: #888;
    word-break: break-all;
}

/* Buttons */
.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn {
    padding: 0.6rem 1.25rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-primary {
    background: #1976d2;
    color: #fff;
}

.btn-primary:hover {
    background: #1565c0;
}

.btn-secondary {
    background: #e0e0e0;
    color: #333;
}

.btn-secondary:hover {
    background: #bdbdbd;
}

.btn-danger {
    background: #e53935;
    color: #fff;
}

.btn-danger:hover {
    background: #c62828;
}

.btn-sm {
    padding: 0.35rem 0.75rem;
    font-size: 0.8rem;
}

/* Toggle switch */
.toggle-group {
    margin-bottom: 1rem;
}

.toggle-label {
    display: flex !important;
    align-items: center;
    gap: 1rem;
    cursor: pointer;
}

.switch {
    position: relative;
    display: inline-block;
    width: 44px;
    height: 24px;
    margin-left: auto;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background-color: #ccc;
    transition: 0.3s;
    border-radius: 24px;
}

.slider::before {
    content: "";
    position: absolute;
    height: 18px;
    width: 18px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    transition: 0.3s;
    border-radius: 50%;
}

.switch input:checked + .slider {
    background-color: #1976d2;
}

.switch input:checked + .slider::before {
    transform: translateX(20px);
}

/* Channels */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.4rem 0;
    font-size: 0.9rem;
}

/* Expandable panel */
.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    padding: 0.85rem 1.25rem;
    background: #f5f5f5;
    border: none;
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 0.95rem;
    font-weight: 500;
}

.panel-header:hover {
    background: #eeeeee;
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid #e0e0e0;
}

/* Status indicator */
.status-indicator {
    font-size: 0.8rem;
    padding: 0.2rem 0.6rem;
    border-radius: 12px;
    font-weight: 500;
}

.status-enabled {
    background: #e8f5e9;
    color: #2e7d32;
}

.status-disabled {
    background: #ffebee;
    color: #c62828;
}

.info-text {
    font-size: 0.85rem;
    color: #777;
    margin: 0.5rem 0;
}

/* Sessions table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.5rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.65rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #eee;
    font-size: 0.9rem;
}

.sessions-table th {
    background: #f5f5f5;
    font-weight: 600;
    color: #555;
}

.current-badge {
    font-size: 0.75rem;
    background: #e3f2fd;
    color: #1976d2;
    padding: 0.2rem 0.5rem;
    border-radius: 10px;
    font-weight: 500;
}

/* Modal */
.modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: #fff;
    padding: 2rem;
    border-radius: 10px;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

.modal-dialog h3 {
    margin-top: 0;
}

/* Radio groups */
.radio-group {
    display: flex;
    gap: 1.5rem;
    margin-top: 0.25rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.9rem;
}

/* Live preview */
.live-preview {
    margin-top: 1.5rem;
    transition: all 0.3s ease;
}

.live-preview h4 {
    margin-top: 0;
    margin-bottom: 0.5rem;
}

namespace sv_6e89210bbe024f549345a964d003f3cb.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@using sv_6e89210bbe024f549345a964d003f3cb.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(toastMessage))
        {
            <div class="toast @toastType">
                @toastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }

        @if (activeSection == "Profile")
        {
            <section class="settings-section">
                <h2>Profile Settings</h2>
                @if (profile is not null)
                {
                    <div class="form-group avatar-group">
                        <label>Avatar</label>
                        <div class="avatar-preview">
                            @if (!string.IsNullOrEmpty(editDisplayName))
                            {
                                <img src="@editAvatarUrl" alt="Avatar" class="avatar-img" />
                            }
                        </div>
                        <span class="avatar-url">@editAvatarUrl</span>
                    </div>
                    <div class="form-group">
                        <label for="displayName">Display Name</label>
                        <input id="displayName" type="text" @bind="editDisplayName" />
                    </div>
                    <div class="form-group">
                        <label for="email">Email</label>
                        <input id="email" type="email" @bind="editEmail" />
                    </div>
                    <div class="form-group">
                        <label for="bio">Bio</label>
                        <textarea id="bio" @bind="editBio" rows="4"></textarea>
                    </div>
                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                        <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                    </div>
                }
                else
                {
                    <p>Loading profile...</p>
                }
            </section>
        }
        else if (activeSection == "Notifications")
        {
            <section class="settings-section">
                <h2>Notification Preferences</h2>
                @if (notificationPrefs is not null)
                {
                    <div class="form-group toggle-group">
                        <label class="toggle-label">
                            <span>Email Notifications</span>
                            <label class="switch">
                                <input type="checkbox" @bind="editEmailNotifications" />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>
                    <div class="form-group toggle-group">
                        <label class="toggle-label">
                            <span>Push Notifications</span>
                            <label class="switch">
                                <input type="checkbox" @bind="editPushNotifications" />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>
                    <div class="form-group toggle-group">
                        <label class="toggle-label">
                            <span>Weekly Digest</span>
                            <label class="switch">
                                <input type="checkbox" @bind="editWeeklyDigest" />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>

                    <h3>Muted Channels</h3>
                    <div class="channel-list">
                        @foreach (var channel in availableChannels)
                        {
                            <label class="channel-item">
                                <input type="checkbox"
                                       checked="@editMutedChannels.Contains(channel)"
                                       @onchange="e => ToggleMutedChannel(channel, (bool)(e.Value ?? false))" />
                                <span>@channel</span>
                            </label>
                        }
                    </div>
                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                    </div>
                }
                else
                {
                    <p>Loading notification preferences...</p>
                }
            </section>
        }
        else if (activeSection == "Security")
        {
            <section class="settings-section">
                <h2>Security Settings</h2>
                @if (securitySettings is not null)
                {
                    <div class="expandable-panel">
                        <button class="panel-header" @onclick="TogglePasswordPanel">
                            <span>Change Password</span>
                            <span class="expand-icon">@(showPasswordPanel ? "▼" : "▶")</span>
                        </button>
                        @if (showPasswordPanel)
                        {
                            <div class="panel-body">
                                <div class="form-group">
                                    <label for="currentPassword">Current Password</label>
                                    <input id="currentPassword" type="password" @bind="currentPassword" />
                                </div>
                                <div class="form-group">
                                    <label for="newPassword">New Password</label>
                                    <input id="newPassword" type="password" @bind="newPassword" />
                                </div>
                                <div class="form-group">
                                    <label for="confirmPassword">Confirm Password</label>
                                    <input id="confirmPassword" type="password" @bind="confirmPassword" />
                                </div>
                                <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                            </div>
                        }
                    </div>

                    <div class="form-group toggle-group">
                        <label class="toggle-label">
                            <span>Two-Factor Authentication</span>
                            <span class="status-indicator @(securitySettings.TwoFactorEnabled ? "status-enabled" : "status-disabled")">
                                @(securitySettings.TwoFactorEnabled ? "Enabled" : "Disabled")
                            </span>
                            <label class="switch">
                                <input type="checkbox" checked="@securitySettings.TwoFactorEnabled" disabled />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>

                    @if (securitySettings.LastPasswordChange.HasValue)
                    {
                        <p class="info-text">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                    }

                    <h3>Active Sessions</h3>
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th>Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in securitySettings.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td>
                                        @if (session != securitySettings.Sessions.First())
                                        {
                                            <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>

                    @if (showRevokeConfirmation)
                    {
                        <div class="modal-overlay">
                            <div class="modal-dialog">
                                <h3>Revoke Session</h3>
                                <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke?.Device</strong> from <strong>@sessionToRevoke?.Location</strong>?</p>
                                <div class="button-group">
                                    <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
                                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                </div>
                            </div>
                        </div>
                    }
                }
                else
                {
                    <p>Loading security settings...</p>
                }
            </section>
        }
        else if (activeSection == "Appearance")
        {
            <section class="settings-section">
                <h2>Appearance Settings</h2>
                @if (appearanceSettings is not null)
                {
                    <div class="form-group">
                        <label>Theme</label>
                        <div class="radio-group">
                            <label class="radio-item">
                                <input type="radio" name="theme" value="Light" checked="@(editTheme == "Light")" @onchange='() => editTheme = "Light"' />
                                <span>Light</span>
                            </label>
                            <label class="radio-item">
                                <input type="radio" name="theme" value="Dark" checked="@(editTheme == "Dark")" @onchange='() => editTheme = "Dark"' />
                                <span>Dark</span>
                            </label>
                            <label class="radio-item">
                                <input type="radio" name="theme" value="System" checked="@(editTheme == "System")" @onchange='() => editTheme = "System"' />
                                <span>System</span>
                            </label>
                        </div>
                    </div>

                    <div class="form-group">
                        <label>Font Size</label>
                        <div class="radio-group">
                            <label class="radio-item">
                                <input type="radio" name="fontSize" value="Small" checked="@(editFontSize == "Small")" @onchange='() => editFontSize = "Small"' />
                                <span>Small</span>
                            </label>
                            <label class="radio-item">
                                <input type="radio" name="fontSize" value="Medium" checked="@(editFontSize == "Medium")" @onchange='() => editFontSize = "Medium"' />
                                <span>Medium</span>
                            </label>
                            <label class="radio-item">
                                <input type="radio" name="fontSize" value="Large" checked="@(editFontSize == "Large")" @onchange='() => editFontSize = "Large"' />
                                <span>Large</span>
                            </label>
                        </div>
                    </div>

                    <div class="form-group">
                        <label for="language">Language</label>
                        <select id="language" @bind="editLanguage">
                            <option value="en">English</option>
                            <option value="es">Spanish</option>
                            <option value="fr">French</option>
                            <option value="de">German</option>
                            <option value="ja">Japanese</option>
                            <option value="zh">Chinese</option>
                        </select>
                    </div>

                    <div class="form-group toggle-group">
                        <label class="toggle-label">
                            <span>Compact Mode</span>
                            <label class="switch">
                                <input type="checkbox" @bind="editCompactMode" />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>

                    <div class="live-preview" style="@GetPreviewStyle()">
                        <h4>Live Preview</h4>
