}

/* Toggle switch */
.toggle-group {
    margin-bottom: 1rem;
}

.toggle-label {
    display: flex !important;
    align-items: center;
    gap: 1rem;
    cursor: pointer;
}

.switch {
    position: relative;
    display: inline-block;
    width: 44px;
    height: 24px;
    margin-left: auto;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background-color: #ccc;
    transition: 0.3s;
    border-radius: 24px;
}

.slider::before {
    content: "";
    position: absolute;
    height: 18px;
    width: 18px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    transition: 0.3s;
    border-radius: 50%;
}

.switch input:checked + .slider {
    background-color: #1976d2;
}

.switch input:checked + .slider::before {
    transform: translateX(20px);
}

/* Channels */
.channel-list {
    display: flex;
