    font-size: 0.9rem;
}

.sessions-table th {
    background: #f5f5f5;
    font-weight: 600;
    color: #555;
}

.current-badge {
    font-size: 0.75rem;
    background: #e3f2fd;
    color: #1976d2;
    padding: 0.2rem 0.5rem;
    border-radius: 10px;
